            y_upper = pos_y + half_height
            if y_lower < 6.0 or y_upper > 8.5:
                in_no_fly = True
                break

    # Calculate platform position
    t = step_count / 60.0
    platform_x = 17.0 + 1.8 * math.sin(2 * math.pi * t / 6.0)
    valid_platform_x = (platform_x - 1.2, platform_x + 1.2)

    # Get linear velocity
    lander = sandbox.get_lander_body()
    linear_velocity = lander.linearVelocity
    vy = linear_velocity.y

    # Get remaining fuel
    fuel = sandbox.get_remaining_fuel()

    # Control logic
    f1 = 0.0
    f2 = 0.0

    if in_no_fly:
        # Adjust thrust to keep y within allowed range
        if pos_y > 8.5:
            f1 = 0.0  # reduce thrust to slow down
        elif pos_y < 6.0:
            f1 = 650.0  # increase thrust to rise
        else:
            f1 = 0.0

