            desired_x = platform_x
            if pos_x < desired_x - 1.2:
                # Land is to the left of platform, tilt right
                f2 = 120.0
            elif pos_x > desired_x + 1.2:
                # Land is to the right of platform, tilt left
                f2 = -120.0
            else:
                f2 = 0.0

        # Apply thrust to control vertical speed, considering fuel
        if fuel < 650:
            f1 = 0.0
        else:
            if vy > 1.0:
                f1 = 650.0
            else:
                f1 = 0.0

    # Apply thrust and torque
    sandbox.apply_thrust(f1, f2)

